using System.Collections.Immutable;

namespace ConfigurationSourceGen.Validations;

public sealed class AllowedValuesValidator : IGenerateValidator {
    public string AttributeName { get; } = "AllowedValuesAttribute";

    public string GenerateAttributeSource(string ns) => $$"""
        // <auto-generated/>
        namespace {{ns}};

        [global::System.AttributeUsage(global::System.AttributeTargets.Property, AllowMultiple = false, Inherited = true)]
        public sealed class AllowedValuesAttribute : global::System.Attribute {
            public string[] Values { get; }

            public AllowedValuesAttribute(params string[] values) {
                Values = values;
            }
        }
        """;

    public void Generate(CodeBuilder builder, ToGenerateProperty property, AttributeDefinition attribute, string valueExpression) {

        if (attribute.Arguments.Count == 0) {
            return;
        }

        builder.If($"!({$"{valueExpression} == " + string.Join($" || {valueExpression} == ", attribute.Arguments)})", () => {
            ValidationGeneratorHelper.AddError(
                builder,
                property.Name,
                "contains a value that is not allowed.");
        });
    }
}